class SpikeFn(torch.autograd.Function):
    @staticmethod
    def forward(ctx, v):
        ctx.save_for_backward(v)
        return (v >= 0).float()          # hard spike
    @staticmethod
    def backward(ctx, grad):
        v, = ctx.saved_tensors
        surrogate = 1.0 / (1.0 + (5*v.abs()))**2   # smooth stand-in
        return grad * surrogate

def rmsnorm(x, gain, eps=1e-6):
    rms = x.pow(2).mean(-1, keepdim=True).add(eps).sqrt()
    return x / rms * gain

import math
def lr_at(step, warm, total, peak, floor=0.0):
    if step < warm:
        return peak * step / warm
    p = (step - warm) / (total - warm)
    return floor + 0.5*(peak-floor)*(1 + math.cos(math.pi*p))
